import { Easing, interpolate } from "remotion";
import { EASE_IN_OUT, EASE_OUT, T } from "../brand/theme";

export type CaptionWord = { text: string; startMs: number; endMs: number };
export type CaptionPage = { startMs: number; endMs: number; lines: CaptionWord[][] };
export type Timeline = {
  version: number;
  fps: number;
  durationMs: number;
  durationInFrames: number;
  /** Normalised copy of Eyad's recording (public/ path). null for silent visual previews. */
  audio: string | null;
  /** Optional sound-effects track (public/ path), generated by make_sfx.py; mixed under the narration. */
  sfx?: string;
  silent: boolean;
  recordingMs?: number;
  timingSource: string;
  captions: CaptionPage[];
  cues: Record<string, number>;
  words: { text: string; startMs: number; endMs: number; score: number }[];
};

/** Frame of a storyboard beat. Beats come from aligned narration (or atMs in silent previews only). */
export const cueFrame = (tl: Timeline, id: string): number => {
  const ms = tl.cues[id];
  if (ms === undefined) {
    throw new Error(`Beat "${id}" missing from timeline.json; add it to the episode storyboard.json`);
  }
  return Math.round((ms / 1000) * tl.fps);
};

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** 0→1 progress starting at `start` over `dur` frames (ease-out). */
export const enter = (frame: number, start: number, dur = T.motion.enterFrames) =>
  interpolate(frame, [start, start + dur], [0, 1], { ...clamp, easing: Easing.bezier(...EASE_OUT) });

/** 1→0 progress (ease-in-out). */
export const exit = (frame: number, start: number, dur = T.motion.enterFrames) =>
  interpolate(frame, [start, start + dur], [1, 0], { ...clamp, easing: Easing.bezier(...EASE_IN_OUT) });

/** Visible between a and b with eased edges. */
export const span = (frame: number, a: number, b: number, dur = T.motion.enterFrames) =>
  Math.min(enter(frame, a, dur), exit(frame, b - dur, dur));

/** Ease-in-out tween of a number between two frames. */
export const tween = (frame: number, a: number, b: number, from: number, to: number) =>
  interpolate(frame, [a, b], [from, to], { ...clamp, easing: Easing.bezier(...EASE_IN_OUT) });

export type Key = { f: number; x: number; y: number; click?: boolean };

/** Position along keyframes; travel eases in-out between consecutive keys. */
export const pathAt = (frame: number, keys: Key[]) => {
  if (frame <= keys[0].f) return { x: keys[0].x, y: keys[0].y };
  for (let i = 0; i < keys.length - 1; i++) {
    const a = keys[i];
    const b = keys[i + 1];
    if (frame <= b.f) {
      const p = interpolate(frame, [a.f, b.f], [0, 1], { ...clamp, easing: Easing.bezier(...EASE_IN_OUT) });
      return { x: a.x + (b.x - a.x) * p, y: a.y + (b.y - a.y) * p };
    }
  }
  const l = keys[keys.length - 1];
  return { x: l.x, y: l.y };
};

/** Press amount (0..1) around click keys, for cursor squash / pulse. */
export const pressAt = (frame: number, keys: Key[], half = 4) => {
  let p = 0;
  for (const k of keys) {
    if (!k.click) continue;
    const d = Math.abs(frame - k.f);
    if (d <= half) p = Math.max(p, 1 - d / half);
  }
  return p;
};
